# -*- coding: utf-8 -*-
import io,sys
h=io.open("index.html",encoding="utf-8").read()
A=chr(39)  # apostrophe
def rep(old,new,label):
    global h
    old=old.replace("^",A); new=new.replace("^",A)
    if old not in h: print("MISSING:",label); sys.exit(1)
    if h.count(old)!=1: print("NOT UNIQUE(%d):"%h.count(old),label); sys.exit(1)
    h=h.replace(old,new); print("ok:",label)

rep('["מזוזה","פתח"]],',
    '["מזוזה","פתח"],["מטאטא","ניקיון"],["דלי","מים"],["ספוג","כלים"],["מגהץ","קמטים"],["פטיש","מסמר"],["מברג","בורג"],["מסמר","קיר"],["חבל","קשירה"],["סולם","גובה"],["כספת","סודי"],["שרפרף","נמוך"],["עציץ","צמח"],["אגרטל","פרחים"],["פמוט","נר"],["מלחייה","תיבול"],["קומקום","רתיחה"],["מחבת","טיגון"],["מגבון","ניגוב"],["סיכה","חד"],["אטב","נייר"]],',"חפצים")
