rep('["גולות","זכוכית"]],',
    '["גולות","זכוכית"],["אמונג אס","חללית"],["רובלוקס","עולמות"],["קנדי קראש","ממתקים"],["אנגרי בירדס","מקלעת"],["סוניק","מהירות"],["זלדה","הרפתקה"],["פיפא","כדורגל"],["ג^נגה","מגדל"],["בינגו","מספרים"],["דומינו","אבנים"],["כסאות מוזיקליים","סיבוב"],["חמש אבנים","זריקה"],["קלאס","קפיצה"],["מחניים","כדור"],["דג מלוח","קיפאון"],["אבן נייר ומספריים","ידיים"],["שבע בום","ספירה"],["בלוף","הונאה"],["פוקר","קלפים"],["סוליטר","קלפים"]],',"משחקים")
